SELECT DATE_TRUNC('YEAR', end_date) AS year_start, CASE WHEN monthly_fee >= 224 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, COUNT(CASE WHEN status = 'EXPIRED' THEN 1 END) AS expired_count, SUM(monthly_fee) FILTER (WHERE status = 'CANCELLED') AS cancelled_total_monthly_fee, APPROX_PERCENTILE(monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_quartiles FROM subscriptions GROUP BY year_start, monthly_fee_tier;
